class PsyanimConsoleLogger {

    log(...args) {
        console.log(...args);
    }

    warn(...args) {
        console.warn(...args);
    }

    error(...args) {
        console.error(...args);
    }
}

export default class PsyanimDebug {

    static log(...args) {

        PsyanimDebug.logger.log(...args);
    }

    static warn(...args) {

        PsyanimDebug.logger.warn(...args);
    }

    static error(...args) {

        PsyanimDebug.logger.error(...args);
    }

    static _vec2ToString(name, vector) {

        let vecString = name + " = ( ";
        vecString += vector.x.toString();
        vecString += ", ";
        vecString += vector.y.toString();
        vecString += " )";

        return vecString;
    }
}

PsyanimDebug.logger = new PsyanimConsoleLogger();